[patterns/application/micro-frontend/PTN-APP-MFE-001-authentication-modernization-pattern.md#phase-1-identity-provider-setup-weeks-1-2]

#### Phase 1: Identity Provider Setup (Weeks 1-2)

1. **Deploy IdentityServer4 (or configure Azure AD B2C)**

   ```csharp
   // IdentityServer4 startup configuration
   services.AddIdentityServer()
       .AddInMemoryClients(new[]
       {
           new Client
           {
               ClientId = "gainwell-spa",
               ClientName = "Gainwell React SPA",
               AllowedGrantTypes = GrantTypes.Code,
               RequirePkce = true, // PKCE required for SPAs
               RequireClientSecret = false, // No secret for public clients
               RedirectUris = { "https://enterprise.gainwell.com/callback" },
               PostLogoutRedirectUris = { "https://enterprise.gainwell.com" },
               AllowedScopes = { "openid", "profile", "email", "api" },
               AccessTokenLifetime = 900, // 15 minutes (HIPAA)
               RefreshTokenUsage = TokenUsage.ReUse,
               RefreshTokenExpiration = TokenExpiration.Absolute,
               AbsoluteRefreshTokenLifetime = 28800 // 8 hours
           }
       })
       .AddInMemoryIdentityResources(new IdentityResource[]
       {
           new IdentityResources.OpenId(),
           new IdentityResources.Profile(),
           new IdentityResources.Email()
       })
       .AddInMemoryApiScopes(new ApiScope[]
       {
           new ApiScope("api", "Gainwell APIs")
       })
       .AddAspNetIdentity<ApplicationUser>() // Integrate with existing user store
       .AddDeveloperSigningCredential(); // Replace with real cert in production
   ```

2. **Configure LDAP/Active Directory Authentication**

   ```csharp
   services.AddAuthentication()
       .AddLdap("ldap", options =>
       {
           options.Host = Configuration["Ldap:Host"];
           options.Port = int.Parse(Configuration["Ldap:Port"]);
           options.BindDn = Configuration["Ldap:BindDn"];
           options.BindCredentials = Configuration["Ldap:BindPassword"];
           options.SearchBase = Configuration["Ldap:SearchBase"];
           options.SearchFilter = Configuration["Ldap:SearchFilter"];
       });
   ```

