[patterns/application/micro-frontend/PTN-APP-MFE-001-authentication-modernization-pattern.md#phase-2-react-authentication-weeks-3-4]

#### Phase 2: React Authentication (Weeks 3-4)

1. **Install @gainwell/auth Package**

   ```bash
   npm install @gainwell/auth
   ```

2. **Configure AuthProvider**

   ```typescript
   // src/main.tsx
   import { AuthProvider } from '@gainwell/auth';

   ReactDOM.createRoot(document.getElementById('root')!).render(
     <AuthProvider
       authority="https://identity.gainwell.com"
       clientId="gainwell-spa"
       redirectUri={window.location.origin + '/callback'}
       scope="openid profile email api"
       sessionTimeout={900000} // 15 minutes in milliseconds (HIPAA)
       onSessionTimeout={() => {
         console.log('HIPAA timeout: No activity for 15 minutes');
         // Redirect to login with message
       }}
     >
       <App />
     </AuthProvider>
   );
   ```

3. **Protect Routes**

   ```typescript
   // src/App.tsx
   import { useAuth, ProtectedRoute } from '@gainwell/auth';

   function App() {
     return (
       <BrowserRouter>
         <Routes>
           <Route path="/login" element={<LoginPage />} />
           <Route path="/callback" element={<CallbackPage />} />

           {/* Protected routes require authentication */}
           <Route element={<ProtectedRoute />}>
             <Route path="/claims" element={<ClaimsPage />} />
             <Route path="/members" element={<MembersPage />} />
             <Route path="/providers" element={<ProvidersPage />} />
           </Route>
         </Routes>
       </BrowserRouter>
     );
   }
   ```

4. **Use Authentication in Components**

   ```typescript
   // src/pages/ClaimsPage.tsx
   import { useAuth } from '@gainwell/auth';

   function ClaimsPage() {
     const { user, accessToken, logout } = useAuth();
     const [claims, setClaims] = useState([]);

     useEffect(() => {
       fetch('/api/claims', {
         headers: {
           'Authorization': `Bearer ${accessToken}`
         }
       })
         .then(res => res.json())
         .then(data => setClaims(data));
     }, [accessToken]);

     return (
       <div>
         <h1>Claims for {user.name}</h1>
         <button onClick={logout}>Logout</button>
         {/* Claims grid */}
       </div>
     );
   }
   ```

